def _coerce_query_int(value):
    if isinstance(value, str):
        if not value or not value.isascii() or not value.isdigit():
            raise ValueError("query parameter must be a non-empty ASCII decimal digit string")
        return int(value)
    return value


def page_query(rows, params):
    if not isinstance(params, dict):
        raise TypeError("params must be a dict")
    offset = _coerce_query_int(params.get("offset", 0))
    limit = _coerce_query_int(params.get("limit", 50))
    return page(rows, offset, limit)
